function minOperations(n) {
  // The lowest set bit must be cleared by adding or subtracting exactly that power; try both.
  const memo = new Map();
  const solve = (value) => {
    if (value === 0) return 0;
    if (memo.has(value)) return memo.get(value);
    const low = value & -value;
    const result = value === low ? 1 : 1 + Math.min(solve(value - low), solve(value + low));
    memo.set(value, result);
    return result;
  };
  return solve(n);
}

