function generate(rand, size) {
  const max = size === 'large' ? 100000 : 300;
  const shape = Math.floor(rand() * 5);
  let n;
  if (shape === 0) n = 2 ** Math.floor(rand() * (size === 'large' ? 17 : 9));
  else if (shape === 1) n = 2 ** (1 + Math.floor(rand() * (size === 'large' ? 16 : 8))) - 1;
  else if (shape === 2) {
    n = 0;
    for (let bit = 0; 2 ** bit <= max; bit++) if (rand() < 0.5) n += 2 ** bit;
    n = Math.max(1, Math.min(max, n));
  } else n = 1 + Math.floor(rand() * max);
  return [n];
}
